#!/usr/bin/env python3
"""Build the workspace stylesheet deterministically, without a Node dependency."""

import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOURCES = (
    "foundation.css",
    "layout.css",
    "controls.css",
    "inventory.css",
    "responsive.css",
    "records.css",
    "loans.css",
    "imports.css",
    "stocktakes.css",
    "navigation.css",
    "states.css",
)
HEADER = (
    "/* Generated by scripts/build_styles.py. Edit assets/styles/, then rebuild. */\n"
)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check", action="store_true", help="Fail if the bundle is stale"
    )
    args = parser.parse_args()
    bundle = HEADER + "\n".join(
        f"/* Source: {name} */\n"
        + (ROOT / "assets" / "styles" / name).read_text(encoding="utf-8").strip()
        + "\n"
        for name in SOURCES
    )
    output = ROOT / "static" / "app.css"
    if args.check:
        if not output.exists() or output.read_text(encoding="utf-8") != bundle:
            parser.exit(1, "Stylesheet is stale. Run: python scripts/build_styles.py\n")
        print("Stylesheet bundle is up to date.")
    else:
        output.write_text(bundle, encoding="utf-8")
        print(f"Built static/app.css from {len(SOURCES)} source files.")


if __name__ == "__main__":
    main()
